    public static long mod(long xi, long yi) {
        long ri = xi % yi;
        if (ri == 0) return 0;

        if (yi > 0) {
            if (xi >= 0) return ri;
            return ri + yi;
        } else {
            if (xi >= 0) return ri + yi;
            return ri;
        }
    }

    public static long pow(long x, long y) {
        long r = 1;
        while (y > 0) {
            if ((y & 1) != 0) {
                r *= x;
                y--;
            }
            x *= x;
            y >>>= 1;
        }
        return r;
    }

